import itertools
import json

def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1 
            deletions = current_row[j] + 1  
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

left_websites = ["https://www.artsdepot.co.uk/", "https://www.bac.org.uk/", "https://www.berniegrantcentre.co.uk/", "https://chatspalace.com/", "https://www.dugdalecentre.co.uk/", "https://harrowarts.com/", "http://www.osoarts.org.uk/", "https://irishculturalcentre.co.uk/", "https://www.jacksonslane.org.uk/", "https://www.jw3.org.uk/", "https://redbridgedramacentre.co.uk/RedbridgeDramaCentre.dll/Home", "https://www.richmix.org.uk/", "https://www.riversidestudios.co.uk/", "https://www.southbankcentre.co.uk/", "https://www.tabernaclew11.com/", "https://www.thealbany.org.uk/", "http://www.hounslowartscentre.co.uk/", "https://www.barbican.org.uk/", "http://www.landmarkartscentre.org/", "https://www.brent.gov.uk/your-council/the-library-at-willesden-green/", "https://www.watermans.org.uk/", "https://poplarunion.com/ ", "https://fairfield.co.uk/", "https://stratford-circus.com/"]
right_websites = ["https://www.hilldrop.org.uk/", "https://barnsburyliving.wordpress.com/", "http://mildmaycp.wordpress.com", "http://www.stjoanofarcparish.co.uk/community-centre", "http://www.octopuscommunities.org.uk/our-projects/community-hubs/about-the-hubs/finsbury-park-community-hub-andover-community-centre/"]

result = []
